 if(target!=null){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;if(self)m.instructions.add(new VarInsnNode(ALOAD,0));else m.instructions.add(new MethodInsnNode(INVOKESTATIC,"com/raiiiden/warborn/hybrid/HybridClient6","beginFrame","()V",false));m.instructions.add(new MethodInsnNode(INVOKESTATIC,V,target,self?"(Ljava/lang/Object;)V":"()V",false));m.instructions.add(new InsnNode(RETURN));bodies++;}
