 public static void main(String[]a)throws Exception{Map<String,byte[]>e=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry en:Collections.list(z.entries())){byte[]b=z.getInputStream(en).readAllBytes();if(en.getName().endsWith("/ShaderRegistry.class")||en.getName().endsWith("/NvgClient2.class"))b=patch(b);e.put(en.getName(),b);}}if(bodies!=2||redirects!=2)throw new AssertionError(bodies+" "+redirects);try(var fs=Files.walk(Path.of(a[2]))){for(Path p:fs.filter(x->x.toString().endsWith(".class")).toList())e.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var x:e.entrySet()){ZipEntry n=new ZipEntry(x.getKey());n.setTime(0);z.putNextEntry(n);z.write(x.getValue());z.closeEntry();}}System.out.println("NVG12_CACHED_PREPARE_FRAME_FOREIGN_EFFECT_PRESERVATION_HOOKS="+(bodies+redirects));}
